type FooterProps = {
  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
  data: FooterConfigEntry;
  copyrightYear?: number;
  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
  initialSubscribed?: boolean;
  /**
   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
   */
  enableNameCapture?: boolean;
  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
   *  noop so the presentational Footer never navigates on its own. */
  onLogoClick?: () => void;
  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
  privacyPolicyHref?: string;
};

// ---------------------------------------------------------------------------
// All footer styling lives in theme/components/footer.ts and is consumed via
// useMultiStyleConfig('ZimmFooter') → __css. Nothing is styled at the call site.
// ---------------------------------------------------------------------------

// Subscribe heading ("Keep in Touch") — same type scale as navigation, distinct colour and lineHeight
// colour.ts note: text.inverseGrey and text.muted are both #969696 as of develop commit 6fa8e92
// lineHeight override: textStyles.navigation says 'normal' (≈14.4px at 12px font), but Figma
// wants 14px, so subscribeHeading sets lineHeight explicitly to --zimm-font-lineheight-2xs.
// These values now live in theme/components/footer.ts's subscribeHeading part, not here.
// ---------------------------------------------------------------------------
// Subscribe modal (HPC-035 + HPC-037)
// Rendered via createPortal so the overlay escapes the footer stacking context.
// ---------------------------------------------------------------------------
// HPC-037 copy — update when UX supplies final content
const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
const ACCESSIBILITY_DISCLAIMER_COPY =
  'Zimmermann is committed to providing accessible services. ' +
  'If you experience any difficulty, please contact us for assistance.';

type SubscribeModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (firstName: string, lastName: string) => void;
  privacyPolicyHref: string;
};

const SubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: SubscribeModalProps) => {
  const { mounted, formRef, firstFocusRef } = useSubscribeModal({ isOpen, onClose });
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});

  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    // namedItem returns Element | RadioNodeList | null. The cast keeps `| null` rather than
    // asserting it away — these fields are always single <input>s rendered by ZimmTextInput,
    // but a missing field must stay a null the `?.` below can actually catch. Same pattern as
    // zimmInputAction's handleSubmit.
    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement | null)?.value ?? '';
    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement | null)?.value ?? '';
    onSubmit(firstName.trim(), lastName.trim());
  };

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) onClose();
  };

  if (!mounted || !isOpen) return null;

  return createPortal(
    <chakra.div role="presentation" onClick={handleBackdropClick} __css={styles.modalOverlay}>
      <chakra.div
        role="dialog"
        aria-modal="true"
        aria-labelledby="zimm-subscribe-modal-title"
        aria-describedby="zimm-subscribe-modal-consent"
        __css={styles.subscribeModalPanel}
      >
        <form ref={formRef} onSubmit={handleFormSubmit} noValidate>
          {/* Title */}
          <chakra.h2 id="zimm-subscribe-modal-title" __css={styles.modalTitle}>
            Join Us
          </chakra.h2>

          {/* First Name */}
          <chakra.div ref={firstFocusRef} __css={styles.modalField}>
            <ZimmTextInput label="First Name" name="firstName" />
          </chakra.div>

          {/* Last Name */}
          <chakra.div __css={styles.modalFieldLast}>
            <ZimmTextInput label="Last Name" name="lastName" />
          </chakra.div>

          {/* Privacy consent copy (HPC-037) */}
          <chakra.p id="zimm-subscribe-modal-consent" __css={styles.modalConsent}>
            {PRIVACY_CONSENT_COPY}{' '}
            {/* Same guard as the contact channels: privacyPolicyHref is a prop, so a caller
                can supply anything. Unsafe or absent renders the label as plain text rather
                than an anchor that goes nowhere. */}
            {isSafeHref(privacyPolicyHref) ? (
              <chakra.a href={privacyPolicyHref} __css={styles.modalConsentLink}>
                Privacy Policy
              </chakra.a>
            ) : (
              <chakra.span __css={styles.modalConsentLink}>Privacy Policy</chakra.span>
            )}
            .
          </chakra.p>

          {/* Accessibility disclaimer (HPC-037) */}
          <chakra.p __css={styles.modalDisclaimer}>{ACCESSIBILITY_DISCLAIMER_COPY}</chakra.p>

          {/* Actions */}
          <chakra.div __css={styles.modalActions}>
            <ZimmButton variant="secondary" size="medium" label="Cancel" type="button" onClick={onClose} />
            <ZimmButton variant="primary" size="medium" label="Continue" type="submit" />
          </chakra.div>
        </form>
      </chakra.div>
    </chakra.div>,
    document.body,
  );
};

// ---------------------------------------------------------------------------
// Subscribe section
// ---------------------------------------------------------------------------
// 'unavailable' shown until HPC-036 (Omneo) lands; prevents false "You're on the list!" feedback.
// 'success'/'error' set only after a confirmed/failed Omneo response (post HPC-036).
type SubmitState = 'idle' | 'unavailable' | 'success' | 'error';

// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
type PendingSignup = { email: string; firstName: string; lastName: string };

type SubscribeSectionProps = {
  heading: string;
  body: string;
  initialSubscribed?: boolean;
  privacyPolicyHref: string;
  enableNameCapture?: boolean;
};

